class Solution {
    public int rob(int[] arr) {
           int ditch=0;
        int curr=0;
        for(int i=0;i<arr.length;i++){
            if(ditch+arr[i]>curr){
                int temp=curr;
                curr=ditch+arr[i];
                ditch=temp;
            }
            else{
                ditch+=arr[i];
                if(ditch<curr)ditch=curr;
                
            }
        }
        return Math.max(ditch,curr);
    }
}

