    lower_bound =0
    upper_bound = len(list)-1
    i = 0
    for i in list:
        if lower_bound <= upper_bound:
            mid_value = (lower_bound + upper_bound)//2

            if list[mid_value] == n:
                globals()['pos'] = mid_value
                return True
            else:
                if list[mid_value] < n:
                   lower_bound = mid_value+1
                else:
                    upper_bound = mid_value-1


