class Solution:
    def isPalindrome(self, s: str) -> bool:
        def isAlphaNumeric(c):
            return (ord('A') <= ord(c) <= ord('Z') or
                    ord('a') <= ord(c) <= ord('z') or
                    ord('0') <= ord(c) <= ord('9'))

        if len(s) <= 1:
            return True

        l = 0
        r = len(s) - 1

        while l < r:
            while l < r and not isAlphaNumeric(c=s[l]):
                l += 1
            while r > l and not isAlphaNumeric(c=s[r]):
                r -= 1

            if s[l].lower() != s[r].lower():
                return False

            l += 1
            r -= 1

        return True

