def permutations_num(nums):
    result = []
    if len(nums) == 1:
        return [nums[:]]
    for _ in range(len(nums)):
        n = nums[0]
        perms = permutations_num(nums[1:])
        for perm in perms:
            perm.append(n) # [2,3]+[1] and [3,2]+[1] individually
        result.extend(perms) # [2,3,1],[3,2,1] all together into the result
    return result

