def searchRange(self, nums: List[int], target: int) -> List[int]:
        low,high=0,len(nums)-1
        left,right=-1,-1
        while(low<=high):
            mid=(low+high)//2
            if nums[mid]==target:
                left=mid
                high=mid-1
            elif nums[mid]<target:
                low=mid+1    
            else:
                high=mid-1
        
        
        low,high=0,len(nums)-1
        
        while(low<=high):
            mid=(low+high)//2
            if nums[mid]==target:
                right=mid
                low=mid+1
            elif nums[mid]<target:
                low=mid+1    
            else:
                high=mid-1
        
        return [left,right]




