def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        cache = {}
        for c in nums:
            if c not in cache:
                cache[c] = 1
            else:
                cache[c] = cache[c] + 1

        cache = dict(sorted(cache.items(), key=lambda i:i[1], reverse=True))
        return list(cache.keys())[:k]

