void setup() {
  size(400, 400);

  img = loadImage("sunflower400.jpg");
  sorted = img.get();
  sorted.loadPixels();

  int selectedPixel = 0;
  int i = 0;

  // Set Colors
  for (int c = 0; c <= 255; c++) {

    // search for the color
    for (int j = i; j < sorted.pixels.length; j++) {

      color pix = sorted.pixels[j];

      // Get hue
      float h = round(hue(pix));

      if (h == c) {
        selectedPixel = j;

        // Swap selectedPixel with i
        color temp = sorted.pixels[i];
        sorted.pixels[i] = sorted.pixels[selectedPixel];
        sorted.pixels[selectedPixel] = temp;

        // set the next destination position
        i++;
      }
    }
  }

  sorted.updatePixels();
}

void draw() {
  background(0);
  image(sorted, 0, 0);
}

