C++ Code for the same -
Note that you need to use i = floor((lo+hi)/2.0) because we want -0.5/2 to evaluate as -1 and not 0.

class Solution {
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size(), m = nums2.size();
        if(m<n) return findMedianSortedArrays(nums2, nums1);
        int half = (n+m)/2;
        int lo = 0, hi = nums1.size()-1;
        int i,j;
        double l1,r1,l2,r2;
        while(true){
           i = floor((lo+hi)/2.0);
           j = half-i-2;
           l1 = i>=0 ? nums1[i] : -INFINITY; 
           r1 = i+1<n ? nums1[i+1] : INFINITY;
           l2 = j>=0 ? nums2[j] : -INFINITY;
           r2 = j+1<m ? nums2[j+1] : INFINITY; 
           if(l1<=r2 and l2<=r1) break; 
           if(l1>r2) hi = i-1;
           else lo = i+1;

        }
        if((n+m)&1) return min(r1,r2);
        else return (max(l1,l2)+min(r1,r2))/2;
    }
};

