I write a function to make the code more neet. Here is my solution: 

class Solution:
    def longestPalindrome(self, s: str) -> str:
        res = ""
        resLen = 0

        def isPalindrome(l, r):
            nonlocal res, resLen
            while l >= 0 and r < len(s) and s[l] == s[r]:
                if (r - l + 1) > resLen:
                    res = s[l:r+1]
                    resLen = r - l + 1
                l, r = l - 1, r + 1

        for i in range(len(s)):
            # odd length
            isPalindrome(i, i)

            # even length
            isPalindrome(i, i + 1)

        return res

