def test_case(cards, query, mid, ascending=True):
    mid_num = cards[mid]
    if mid_num == query:
        return 'found'
    elif ascending:
        if mid_num < query:
            return 'right'
        else:
            return 'left'
    else:  # Descending order
        if mid_num < query:
            return 'left'
        else:
            return 'right'

def locate_card(cards, query, ascending=True):
    lo, hi = 0, len(cards) - 1

    while lo <= hi:
        mid = (lo + hi) // 2
        result = test_case(cards, query, mid, ascending)

        if result == 'found':
            return mid
        elif result == 'left':
            hi = mid - 1
        elif result == 'right':
            lo = mid + 1

    return -1

