If you are familiar with Ultimate Binary Search, then using a lower bound to find the first right element from nums1, which is bigger or equal to the corresponding 'remaining' left element from nums2, might be easier:

var findMedianSortedArrays = function(nums1, nums2) {
    if (nums1.length > nums2.length) {
        [nums1, nums2] = [nums2, nums1];
    }

    const totalLength = nums1.length + nums2.length;
    const halfLength = Math.floor((totalLength + 1) / 2);

    let left = 0;
    let right = nums1.length;

    while (left < right) {
        const mid1 = Math.floor((left + right) / 2);
        const mid2 = halfLength - mid1;

        if (nums1[mid1] >= nums2[mid2 - 1]) {
            right = mid1;
        } else {
            left = mid1 + 1;
        }
    }

    const mid1 = left;
    const mid2 = halfLength - mid1;

    let maxLeft, minRight;
    const LB1 = mid1 -1
    const LB2 = mid2 - 1
    const RB1 = mid1
    const RB2 = mid2

    if (LB1 < 0) {
        maxLeft = nums2[LB2];
    } else if (LB2 < 0) {
        maxLeft = nums1[LB1];
    } else {
        maxLeft = Math.max(nums1[LB1], nums2[LB2]);
    }

    if (RB1 === nums1.length) {
        minRight = nums2[RB2];
    } else if (RB2 === nums2.length) {
        minRight = nums1[RB1];
    } else {
        minRight = Math.min(nums1[RB1], nums2[RB2]);
    };

    if (totalLength % 2 === 0) {
        return (maxLeft + minRight) / 2;
    } else {
        return maxLeft;
    }
};

