class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        
        while l <= r:
            mid = (l + r) // 2

           if nums[mid] == target:
                return mid
                
            # FYI if nums[mid] >= nums[r], then that means the diverging point is in the second half
            if ( (target <= nums[r] and target >= nums[mid]) or (nums[mid] >= nums[r] and (target <= nums[r] or target >= nums[mid] )) ):
                l = mid + 1
            else:
                r = mid - 1
        
        return -1

