class Solution:
    def permute(self, nums):
        res =[]
        perm= []
        def dfs():
            if len(perm) == len(nums):
                res.append(perm.copy())
                return

            for n in nums:
                if n not in perm:
                    perm.append(n)
                    dfs()
                    perm.pop()

        dfs()
        return res

