class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:

        if len(nums) <= 1:
            return [nums]
        return [[nums[i]] + j for i in range(len(nums)) for j in self.permute((nums[:i] + nums[i+1:])) ]

To anyone who is still confused, here's a solution which is easier to understand with comments:
class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            m = (l + r) // 2
            if nums[m] == target:
                return m
            # left portion
            elif nums[l] <= nums[m]:
                # target is in left portion
                if nums[l] <= target < nums[m]:
                    r = m-1
                # can be in either, because there are still elements bigger and smaller than target in the array, but remove left side of m
                else:
                    l = m+1
            # right portion
            else:
                # sure target is in right portion
                if nums[m] < target <= nums[r]:
                    l = m+1
                # can be in either, because there are still elements bigger and smaller than target in the array, but remove right side of m
                else:
                    r = m-1
        return -1

def binary(arr, key):
    return binarySearch(arr, key, 0, len(arr))

def binarySearch(arr, key, left, right):
    if left<=right:
        middle = int((left+right)/2)
        if arr[middle]==key:
            return middle
        elif arr[middle]>key:
            return binarySearch(arr, key, left, middle-1)
        else:
            return binarySearch(arr, key, middle+1, right)
    else:
        return "Not found"


