class Solution {
public:
    int search(vector<int>& nums, int target) {
        int size = nums.size();
        if (size == 0) {
            return -1;
        }

        // Handle the case where size == 1
        if (size == 1) {
            return (nums[0] == target) ? 0 : -1;
        }

        int res = -1;
        int l = 0;
        int r = size - 1;

        while (l <= r) {
            int mid = (r + l) / 2;

            // Check if nums[mid] is the target
            if (nums[mid] == target) {
                res = mid;
                break;
            }

            // Check if nums[l] is the target
            if (nums[l] == target) {
                res = l;
                break;
            }

            // Check if nums[r] is the target
            if (nums[r] == target) {
                res = r;
                break;
            }

            // Determine which part of the array is sorted
            if (nums[mid] > nums[l] && nums[mid] > nums[r]) {
                if (target >= nums[l] && target < nums[mid]) {
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            } else {
                // Prevent r from becoming negative
                if (r > 0) {
                    r = r - 1;
                } else {
                    break; // Exit if r is already 0
                }
            }
        }

        return res;
    }
};

