var longestPalindrome = function(s) {
  const map = s.split('').reduce((acc, curr) => {
    acc[curr] ??=0;
    acc[curr]++;
    return acc;
  }, {});

  let seen = false;
  count = 0;

  Object.values(map).forEach(el => {
    if (el % 2 === 1) {
      if (!seen) {
        count += el;
        seen = true;
      } else {
        count += el -1;
      }
    } else {
      count += el;
    }
  });

  return count;
};

