You can use only hash map to solve this problem with O(1)

var LRUCache = function(capacity) {
    this.cache = new Map();
    this.capacity = capacity;
};

LRUCache.prototype.get = function(key) {
    if (!this.cache.has(key)) return -1;

    const v = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, v);
    return this.cache.get(key);
};

LRUCache.prototype.put = function(key, value) {
    if (this.cache.has(key)) this.cache.delete(key);
    
    this.cache.set(key, value);

    if (this.cache.size > this.capacity) 
        this.cache.delete(this.cache.keys().next().value);  // keys().next().value returns first item's key
    
};

Both accessing the first key's value and deleting an item from a map are O(1) in JavaScript.
For map.keys().next().value in JavaScript, each step (getting keys, moving to the next item, and getting its value) operates in constant time, making the overall complexity O(1), or "constant time." This means it takes the same amount of time to execute regardless of the size of the map.

My solution in Javascript, if anyone needs it :) It's a little different from NeetCode's solution, which i also emulated later in JS but it showed worse memory and runtime on Leetcode. 
var topKFrequent = function (nums, k) {
  const count = {};
  for (let i = 0; i < nums.length; i++) {
    if (count.hasOwnProperty(nums[i])) {
      count[nums[i]] += 1;
    } else count[nums[i]] = 1;
  }
  // you cant sort objects, so move values into an array of two element arrays
  // where 0-idx element is the number and 1-idx element is the count of its occurrences
  const sortedArr = [];
  for (let num in count) {
    sortedArr.push([num, count[num]]);
  }

  //sort in descending order
  sortedArr.sort(function (a, b) {
    return b[1] - a[1];
  });

  const res = [];
  for (let i = 0; i < k; i++) {
    res.push(Number(sortedArr[i][0]));
  }
  return res;
};

