function isPalindrome(s: string): boolean {
  const alphanumericOnly = s.replace(/[^a-zA-Z0-9]/g, "").toLowerCase();
  const reversed = alphanumericOnly.split("").reverse().join("");
  return alphanumericOnly === reversed;
}

