class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        n = len(nums)
        ans = []
        used = set()
        def dfs(arr):
            if len(arr) == n:
                ans.append(arr.copy())
                return
            
            for num in nums:
                if num not in used:
                    used.add(num)
                    arr.append(num)
                    dfs(arr)
                    arr.pop()
                    used.remove(num)
        dfs([])
        return ans

