class Solution {
    public String longestPalindrome(String s) {
        String res= "";
        int resLength=0;
        int l,r;
        int n= s.length();
        for(int i=0;i<n;i++){
            //odd length
            l=i;r=i;
            while(l>=0 && r<n && s.charAt(l)==s.charAt(r)){
                if(r-l+1>=resLength){
                    resLength = r-l+1;
                    res = s.substring(l,r+1);
                }
                r++;
                l--;
            }
            //even length
            l=i;
            r=i+1;
            while(l>=0 && r<n && s.charAt(l)==s.charAt(r)){
                if(r-l+1>=resLength){
                    resLength = r-l+1;
                    res = s.substring(l,r+1);
                }
                r++;
                l--;
            }
        }
        return res;
    }
}

