class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l = 0
        r = len(nums) - 1
        while l<=r:
            mid = (l+r) //2
            if nums[mid] ==target:
                return mid
            if nums[l] <= target < nums[mid] or target <= nums[mid] <=nums[r] or nums[mid] < nums[l] <= target:
                r = mid -1 
            else:
                l = mid + 1
        return -1

