def permute(self, nums: List[int]) -> List[List[int]]:
        
        output = []
        
        def backtracking(res):
            if len(res) == len(nums):
                output.append(list(res))
                
                
            for i in nums:
                if i not in res:
                    res.append(i)
                    backtracking(res)
                    res.pop()
                    
                    
        backtracking([])
        
        return output

