from abc import ABC, abstractmethod # library for OOP

class Channel:
    def __init__(self, name) -> None:
        self.name = name
        self.subscribers = [] # list

    def channel_subscription(self, sub):
        self.subscribers.append(sub) # add to list

    def notify(self, event):
        for sub in self.subscribers:
            sub.notification(self.name, event)

class Subscriber(ABC): # abstract class
    @abstractmethod # decorator
    def send_notification(self, event): # implemented in child class
        pass # abstract model of the method

class User(Subscriber):
    def __init__(self, name) -> None:
        self.name = name # Name of the user

    def send_notification(self, channel, event): # override of the method
        print(f"User: {self.name} received notification form {channel} {event}")

chan = Channel("MyChannel") # instance of the class with the list
chan.channel_subscription(Subscriber("sub1")) # dependency injection
chan.channel_subscription(Subscriber("sub2"))
chan.channel_subscription(Subscriber("sub3"))
