class Node():
    def __init__(self, val) -> None:
        self.val = val # data in node
        self.next = None # assume is empty

class LinkedList:
    def __init__(self, head) -> None:
        self.head = head # first in the list
        self.current = None

    def __iter__(self):
        self.current = self.head
        return self # reference constructor
    
    def __next__(self):
        if self.current:
            val = self.current.val # current value
            self.current = self.current.next # jump to the next node
            return val # return the value
        else: # custom exception
            raise StopIteration ("No more nodes to iterate over")

