from abc import ABC, abstractmethod

class FilterStrategy(ABC): # abstract class

    @abstractmethod # implemented in child classes
    def remove_value(self, val):
        pass # modelation of method

class RemoveNegativeStrategy(FilterStrategy): # inheritance
    def remove_value(self, val):
        return val < 0 # less than 0
    
class RemoveOddStrategy(FilterStrategy): # inheritance
    def remove_value(self, val):
        return abs(val) % 2

class Values:
    def __init__(self, values) -> None:
        self.values = values

    def filter_values(self, strategy): # use a class a parameter
        result = []
        for n in self.values: # check values
            if not strategy.remove_value(n): # iteration element
                result.append(n) # get the item
        return result # show it

values = Values([-7, -4, -1, 0, 2, 6, 9]) # list of items
print(values.filter_values(RemoveNegativeStrategy())) # class as argument

