class Solution:
    def rob(self, nums: List[int]) -> int:
        length = len(nums)
        if length <2: return nums[0]
        
        for i in range(length-3, -1,-1):
            nums[i] += max(nums[i+2] if i+2<length else 0, nums[i+3] if i+3<length else 0)
        
        return max(nums[0], nums[1])

