Just wanted to share my solution. It did pretty well and It's quite simple:
def isPalindrome(self, s: str) -> bool:
        new_s = ""
        for i in range(len(s)):
            if 96 < ord(s[i]) < 123 or 47 < ord(s[i]) < 58:
                new_s += s[i]
                continue
            if 64 < ord(s[i]) < 91:
                new_s += chr(ord(s[i]) + 32)
                continue

        return new_s == new_s[::-1]

