var findMedianSortedArrays = function(nums1, nums2) {
    let [a,b] = [nums1, nums2];
    const total = a.length + b.length;
    const half = Math.floor(total / 2);
    if (a.length > b.length) {
        [a, b] = [b, a];
    }

    let left = 0;
    let right = a.length - 1;

    while (true) {
        let i = Math.floor((left + right) / 2);
        let j = half - i - 2;

        aLeft = i >= 0 ? a[i] : -Infinity;
        aRight = i + 1 < a.length ? a[i + 1] : Infinity;
        bLeft = j >= 0 ? b[j] : -Infinity;
        bRight = j + 1 < b.length ? b[j + 1] : Infinity;

        if (aLeft <= bRight && bLeft <= aRight) {
            const leftMedian = Math.max(aLeft, bLeft);
            const rightMedian = Math.min(aRight, bRight);
            if (total % 2 === 0) {
                return Math.floor((leftMedian + rightMedian) / 2);
            } else {
                return Math.floor((rightMedian) / 2)
            }
        } if (aLeft > bRight) {
            right = i - 1;
        } else {
            left = i + 1;
        }
    }
