class Solution:
    def rotate(self, matrix: List[List[int]]) -> None:
        N = len(matrix)

        for y in range(N // 2):
            for x in range(y, N - y - 1):
                rot_x, rot_y = x, y

                for i in range(3):
                    matrix[rot_y][rot_x], matrix[-rot_x - 1][rot_y] = (
                        matrix[-rot_x - 1][rot_y],
                        matrix[rot_y][rot_x],
