my solution with top down approach dp: (I also did a step by step thought process explanation in leetcode)

class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]        
        res = 0
        def dp(i):
            if i < 0:
                return

            tmp1, tmp2 = 0, 0
            if i + 2 < len(nums):
                tmp1 = nums[i+2]
            if i + 3 < len(nums):
                tmp2 = nums[i+3]
            nums[i] += max(tmp1, tmp2)
            dp(i-1)
        dp(len(nums)-1)
        return max(nums[0],nums[1])

