class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        curr_sum = 0
        count = 0
        sum_to_count = collections.defaultdict(int)

        for n in nums:
            curr_sum += n

            if curr_sum == k:
                count += 1

            count += sum_to_count[curr_sum - k]

            sum_to_count[curr_sum] += 1

        return count

